patternCss:
.bds-pattern-query-list {
  --bds-pattern-page-max-width: 1280px;
  --bds-pattern-page-padding-x: 32px;
  --bds-pattern-page-padding-y: 28px;
  --bds-pattern-section-gap: 20px;
  --bds-pattern-header-gap: 12px;
  --bds-pattern-header-action-alignment: start;
  --bds-pattern-content-padding: 0px;
  --bds-pattern-content-radius: 0;
  --bds-pattern-filter-columns: 2;
  --bds-pattern-filter-row-gap: 16px;
  --bds-pattern-filter-column-gap: 16px;
  --bds-pattern-field-min-width: 260px;
  --bds-pattern-field-max-width: 360px;
  --bds-pattern-filter-padding: 16px;
  --bds-pattern-filter-bg: var(--bds-bg-surface, transparent);
  --bds-pattern-filter-radius: var(--bds-radius-md, 6px);
  --bds-pattern-results-gap: 16px;
  --bds-pattern-results-padding: 0px;
  --bds-pattern-results-bg: transparent;
  --bds-pattern-results-header-alignment: space-between;
  --bds-pattern-pagination-alignment: center;
  --bds-pattern-pagination-gap: 16px;
  /* 分页单行（paginationSingleLine）：Desktop / Tablet 不换行；Compact 由下方断点放开 */
  --bds-pattern-pagination-wrap: nowrap;
  --bds-pattern-pagination-compact-mode: window-shrink-then-hide-boundary;
  --bds-pattern-table-min-width: 800px;
  --bds-pattern-action-alignment: end;
  --bds-pattern-actions-wrap: nowrap;
  --bds-pattern-compact-actions-full: 1;
  --bds-pattern-compact-pagination-wrap: stack;
}

@media (max-width: 1100px) {
  .bds-pattern-query-list {
    --bds-pattern-filter-columns: 2;
    --bds-pattern-actions-wrap: wrap;
    --bds-pattern-page-max-width: none;
  }
}

@media (max-width: 640px) {
  .bds-pattern-query-list {
    --bds-pattern-filter-columns: 1;
    --bds-pattern-table-min-width: 600px;
    --bds-pattern-pagination-alignment: center;
    /* Compact 收敛（paginationCompactMode）：放开单行换行；组件侧同步隐藏首页 / 末页
       与远离当前页的页码（保留上一页 / 当前页 / 下一页），不堆成凌乱多行 */
    --bds-pattern-pagination-wrap: wrap;
  }
}
